"""Build a read-only local review from recorded evidence; never assign verdicts."""
import html,json
from pathlib import Path
from measure_fluidity import ROOT
OUT=ROOT/'Verification/Evidence/PowerWarmup'
def run():
    report=json.loads((OUT/'Performance_Comparison.json').read_text());rows=[]
    for r in report['rows']:
        rows.append('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in [r['folder'],r['kind'],r['frames'],r['twoPlusRefreshIntervals'],r['threePlusRefreshIntervals'],f"{r['p95IntervalMs']:.2f}",f"{r['worstIntervalMs']:.2f}",f"{r['p95RenderMs']:.2f}",r['poolGrowth'],r['combatSpriteCreates'],f"{r['medianPreparationSeconds']:.2f}"] )+'</tr>')
    visual=json.loads((OUT/'Visual_Review.json').read_text());ui=json.loads((OUT/'UI_Review.json').read_text());source=json.loads((OUT/'Player_Source_SHA256.json').read_text());summary=json.loads((OUT/'Verification_Summary.json').read_text())
    aggregates="".join("<tr>"+"".join(f"<td>{html.escape(str(v))}</td>" for v in [r["control"],r["kind"],f"{r['p95RenderMs']:.2f}",r["poolGrowth"],r["threePlusRefreshIntervals"],r["frames"]])+"</tr>" for r in report["aggregatedControls"])
    main={(r["control"],r["kind"]):r for r in report["aggregatedControls"]}
    baselineOrb=main[("Baseline","orb_rocket")];candidateOrb=main[("Candidate","orb_rocket")];baselineGolden=main[("Baseline","golden_bomb")];candidateGolden=main[("Candidate","golden_bomb")]
    images=''.join(f'<figure><figcaption>{html.escape(n)}</figcaption><a href="{html.escape(n)}"><img loading="lazy" src="{html.escape(n)}"></a></figure>' for n in visual['plates']+ui.get('plates',[]))
    content=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Power presentation follow-up</title><style>body{{font:16px system-ui;background:#131b25;color:#e6edf3;max-width:1400px;margin:30px auto;padding:16px}}a{{color:#9bd9f9}}p{{max-width:1000px;line-height:1.5}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{border:1px solid #526272;padding:8px;text-align:left}}img{{max-width:100%;height:auto}}figure{{margin:32px 0}}code{{word-break:break-all}}</style><h1>Power presentation follow-up</h1><p>{html.escape(summary['status'])}. Unity 2022.3.62f3; Android development APK <code>{source['apk_sha256']}</code>. {summary['current_android_regression']['checks']} native Android checks, 50 boards; eight actual gesture cases reviewed.</p><p>Prepared common native sprites and renderer capacity before input; retained and reset the renderer pool on reload. Validated sprite-cache hits avoid repeat native texture queries. Gameplay rules, artwork and level files are unchanged.</p><h2>Repeated main controls</h2><p>Six repetitions per combo per main control across two app processes. Measured p95 rendering sections fell from {baselineOrb["p95RenderMs"]:.2f} to {candidateOrb["p95RenderMs"]:.2f} ms (Orb+Rocket) and {baselineGolden["p95RenderMs"]:.2f} to {candidateGolden["p95RenderMs"]:.2f} ms (Golden+Bomb). Board-reload preparation rises from about {baselineOrb["medianPreparationSeconds"]:.2f} to {candidateOrb["medianPreparationSeconds"]:.2f} seconds. Cold command stalls remain, including a {candidateOrb["worstIntervalMs"]:.2f} ms candidate interval. Timings are elapsed work sections including scheduling/preemption, not OS thread utilization.</p><table><tr><th>Control</th><th>Combo</th><th>p95 render ms</th><th>New renderers</th><th>3+ refresh intervals</th><th>Frames</th></tr>{aggregates}</table><h2>All same-APK controls</h2><p>Three repetitions of each combo per process, same seed and emulator. Baseline and candidate repeat in reverse order; no recording/readback during timing. Baseline disables both changes; WarmOnly enables preparation/pool retention; CacheOnly enables fast lookup; Candidate enables both. Preparation seconds are outside gameplay. Frame intervals include GPU/emulator scheduling. Render CPU is separate from command CPU. Counts use thresholds between refresh multiples: &gt;25ms and &gt;41.7ms. Strict 33.34/50 ms counts are sensitive to display-clock rounding. No sustained 60 fps or physical-device certification.</p><table><tr><th>Control</th><th>Combo</th><th>Frames</th><th>2+ refresh intervals</th><th>3+ refresh intervals</th><th>p95 interval ms</th><th>Worst interval ms</th><th>p95 render CPU ms</th><th>New renderers</th><th>Combat sprite creates</th><th>Median prep s</th></tr>{''.join(rows)}</table><p><a href="Performance_Comparison.json">Measurements and scope</a> · <a href="Native_Checks.json">Native lifecycle checks</a> · <a href="LDPlayer/Regression.json">Current Android regression</a> · <a href="Verification_Summary.json">Full verification summary</a></p><h2>Native visual review</h2><p>Actual swipe recordings sampled into plates; video cadence is not a performance benchmark. Review covers creation, hit chaining, obstacle clearance/refill and selected app UI. <a href="../GameplayAudit/Comparison.html">Earlier Match Villains v7307 comparison</a> retains its original date/APK scope; no new competitor parity claim.</p>{images}<p>Final Home captures: <a href="MainInstance_Launch.png">Original LDPlayer</a> and <a href="QA_Launch.png">QA LDPlayer</a>.</p><h2>Remaining limits</h2><ul>{''.join('<li>'+html.escape(n)+'</li>' for n in summary['remaining'])}</ul></html>'''
    (OUT/'Comparison.html').write_text(content,encoding='utf-8');print(OUT/'Comparison.html')
if __name__=='__main__':run()
